    return y * 0.05
def on_round_end(r):
    for a in agents("Legislator"):
        if balance("reserve", "timber") >= 1:
            move("reserve", a, "timber", 1)
","intent":"Small 5% harvest levy into the reserve; it pays each Legislator up to 1 timber per round. No minting."}

